def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch, pre-release).
    Handles optional pre-release identifiers (e.g., "1.0.0-alpha").
    """
    import re
    def _parse(v: str):
        # Split into main and pre-release
        main, _, pre = v.partition('-')
        major, minor, patch = map(int, main.split('.'))
        pre_parts = []
        if pre:
            for part in re.split(r'\.|-', pre):
                if part.isdigit():
                    pre_parts.append((int(part), 'num'))
                else:
                    pre_parts.append((part, 'str'))
        return (major, minor, patch, pre_parts)
    # Sort using parsed key
    return sorted(vs, key=_parse)

