from functools import lru_cache

@lru_cache(maxsize=1)
def _load_rates():
    path = pathlib.Path(__file__).parent.parent / 'config' / 'tax_rates_2025.json'
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception:
        return {}


def state_tax(state: str, amount: float) -> float:
    """Sales tax owed on amount, using the rate table in config/tax_rates_2025.json."""
    rates = _load_rates()
    rate = rates.get(state.upper(), 0.0)
    return round(amount * rate, 2)

